using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type={personInfo.Type.Name}, " +
                  $"Properties={personInfo.Properties.Count}");

// Use the typed metadata to serialize
string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a. Type that IS resolvable (default reflection resolver handles it)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGet Person  → found ({found!.Type.Name})");
else
    Console.WriteLine("TryGet Person  → not found");

// 2b. Type that is NOT resolvable (empty resolver → nothing registered)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()  // overridden below
};
// Replace the resolver with one that resolves nothing
empty.TypeInfoResolver = JsonTypeInfoResolver.Combine();   // no resolvers

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
    Console.WriteLine($"TryGet (empty) → found ({missing!.Type.Name})");
else
    Console.WriteLine("TryGet (empty) → not found (no exception thrown!)");

// --- done ---
public record Person(string Name, int Age);

